namespace FormatFactoryWinUI.Services;

internal static class MediaCompatibilityLocalizationResources
{
    internal static LocalizedResourceModule Module { get; } = new("MediaCompatibility",
    [
        new("MediaCompatibilityAacOption", ["Use compatible stereo audio (AAC)","使用兼容立体声音轨（AAC）","使用相容立體聲音軌（AAC）","互換ステレオ音声（AAC）を使用","호환 스테레오 오디오(AAC) 사용","Usar audio estéreo compatible (AAC)","Utiliser l’audio stéréo compatible (AAC)","Kompatibles Stereo-Audio verwenden (AAC)","Usar áudio estéreo compatível (AAC)","Использовать совместимое стереоаудио (AAC)","Usa audio stereo compatibile (AAC)","Compatibele stereo-audio gebruiken (AAC)","Użyj zgodnego dźwięku stereo (AAC)","Uyumlu stereo ses kullan (AAC)","استخدام صوت ستيريو متوافق (AAC)"]),
        new("MediaCompatibilityAacWarning", ["Outputs only the AAC stereo track. APAC spatial audio and other audio tracks are not included.","仅输出 AAC 立体声音轨，不包含 APAC 空间音频和其他音轨。","僅輸出 AAC 立體聲音軌，不包含 APAC 空間音訊和其他音軌。","AAC のステレオ音声トラックのみを出力します。APAC の空間オーディオとその他の音声トラックは含まれません。","AAC 스테레오 오디오 트랙만 출력합니다. APAC 공간 오디오와 다른 오디오 트랙은 포함되지 않습니다.","Solo se emite la pista estéreo AAC. No se incluyen el audio espacial APAC ni las demás pistas de audio.","Seule la piste stéréo AAC est produite. L’audio spatial APAC et les autres pistes audio ne sont pas inclus.","Nur die AAC-Stereospur wird ausgegeben. Räumliches APAC-Audio und andere Audiospuren sind nicht enthalten.","Somente a faixa estéreo AAC será gerada. O áudio espacial APAC e as outras faixas de áudio não serão incluídos.","Выводится только стереодорожка AAC. Пространственное аудио APAC и другие аудиодорожки не включаются.","Viene prodotta solo la traccia stereo AAC. L’audio spaziale APAC e le altre tracce audio non sono inclusi.","Alleen de AAC-stereotrack wordt uitgevoerd. Ruimtelijke APAC-audio en andere audiotracks worden niet opgenomen.","Wyjście zawiera tylko ścieżkę stereo AAC. Dźwięk przestrzenny APAC i inne ścieżki audio nie są uwzględniane.","Yalnızca AAC stereo ses parçası çıkarılır. APAC uzamsal ses ve diğer ses parçaları dahil edilmez.","يتم إخراج مسار AAC الستيريو فقط. لا يتم تضمين صوت APAC المكاني أو مسارات الصوت الأخرى."]),
        new("MediaCompatibilityAacUnavailable", ["This file does not have an AAC stereo track alongside APAC. APAC decoding requires a supported decoder.","此文件没有与 APAC 并存的 AAC 立体声音轨。解码 APAC 需要支持该格式的解码器。","此檔案沒有與 APAC 並存的 AAC 立體聲音軌。解碼 APAC 需要支援該格式的解碼器。","このファイルには APAC と併存する AAC ステレオ音声トラックがありません。APAC のデコードには対応するデコーダーが必要です。","이 파일에는 APAC와 함께 있는 AAC 스테레오 트랙이 없습니다. APAC를 디코딩하려면 지원하는 디코더가 필요합니다.","Este archivo no tiene una pista estéreo AAC junto a APAC. La decodificación de APAC requiere un decodificador compatible.","Ce fichier ne contient pas de piste stéréo AAC aux côtés d’APAC. Le décodage APAC nécessite un décodeur compatible.","Diese Datei enthält neben APAC keine AAC-Stereospur. Zum Decodieren von APAC wird ein unterstützter Decoder benötigt.","Este arquivo não tem uma faixa estéreo AAC junto com APAC. A decodificação de APAC exige um decodificador compatível.","В этом файле нет стереодорожки AAC вместе с APAC. Для декодирования APAC нужен поддерживающий его декодер.","Questo file non contiene una traccia stereo AAC insieme ad APAC. La decodifica APAC richiede un decodificatore supportato.","Dit bestand heeft geen AAC-stereotrack naast APAC. Voor APAC-decodering is een ondersteunde decoder nodig.","Ten plik nie ma ścieżki stereo AAC obok APAC. Dekodowanie APAC wymaga obsługującego go dekodera.","Bu dosyada APAC ile birlikte bir AAC stereo ses parçası yok. APAC kod çözme işlemi desteklenen bir kod çözücü gerektirir.","لا يحتوي هذا الملف على مسار AAC ستيريو بجانب APAC. يتطلب فك ترميز APAC وحدة فك ترميز تدعمه."]),
        new("MediaCompatibilityAacLossless", ["Compatible audio cannot be used in lossless mode because it omits audio tracks.","兼容音轨会省略音轨，无法在无损模式下使用。","相容音軌會省略音軌，無法在無損模式下使用。","音声トラックが省略されるため、ロスレスモードでは互換音声を使用できません。","오디오 트랙이 생략되므로 무손실 모드에서는 호환 오디오를 사용할 수 없습니다.","El audio compatible no puede usarse en modo sin pérdida porque omite pistas de audio.","L’audio compatible ne peut pas être utilisé en mode sans perte, car il omet des pistes audio.","Kompatibles Audio kann im verlustfreien Modus nicht verwendet werden, da es Audiospuren auslässt.","O áudio compatível não pode ser usado no modo sem perdas porque omite faixas de áudio.","Совместимое аудио нельзя использовать в режиме без потерь, так как оно исключает аудиодорожки.","L’audio compatibile non può essere usato in modalità senza perdita perché omette tracce audio.","Compatibele audio kan niet in de verliesvrije modus worden gebruikt omdat audiotracks worden weggelaten.","Zgodnego dźwięku nie można używać w trybie bezstratnym, ponieważ pomija ścieżki audio.","Ses parçalarını dışarıda bıraktığı için uyumlu ses kayıpsız modda kullanılamaz.","لا يمكن استخدام الصوت المتوافق في الوضع دون فقد لأنه يستبعد مسارات صوتية."]),
        new("MediaCompatibilityAacSelectionFailed", ["The compatible audio selection cannot be used. {0}","无法使用所选兼容音轨。{0}","無法使用所選相容音軌。{0}","選択した互換音声は使用できません。{0}","선택한 호환 오디오를 사용할 수 없습니다. {0}","No se puede usar la selección de audio compatible. {0}","La sélection audio compatible ne peut pas être utilisée. {0}","Die Auswahl des kompatiblen Audios kann nicht verwendet werden. {0}","Não é possível usar a seleção de áudio compatível. {0}","Выбранное совместимое аудио нельзя использовать. {0}","La selezione audio compatibile non può essere usata. {0}","De selectie van compatibele audio kan niet worden gebruikt. {0}","Nie można użyć wybranego zgodnego dźwięku. {0}","Uyumlu ses seçimi kullanılamıyor. {0}","لا يمكن استخدام اختيار الصوت المتوافق. {0}"]),
        new("MediaCompatibilityEngineTitle", ["Compatibility decoder", "兼容解码引擎", "相容解碼引擎", "互換デコーダー", "호환 디코더", "Decodificador compatible", "Décodeur compatible", "Kompatibler Decoder", "Decodificador compatível", "Совместимый декодер", "Decodificatore compatibile", "Compatibele decoder", "Zgodny dekoder", "Uyumlu kod çözücü", "وحدة فك ترميز متوافقة"]),
        new("MediaCompatibilityEnginePlaceholder", ["Automatic (bundled) or ffmpeg.exe path", "自动使用内置引擎，或填写 ffmpeg.exe 路径", "自動使用內建引擎，或填寫 ffmpeg.exe 路徑", "自動（内蔵）、または ffmpeg.exe のパス", "자동(내장) 또는 ffmpeg.exe 경로", "Automático (incluido) o ruta de ffmpeg.exe", "Automatique (fourni) ou chemin de ffmpeg.exe", "Automatisch (mitgeliefert) oder ffmpeg.exe-Pfad", "Automático (incluído) ou caminho do ffmpeg.exe", "Автоматически (встроенный) или путь ffmpeg.exe", "Automatico (incluso) o percorso ffmpeg.exe", "Automatisch (meegeleverd) of ffmpeg.exe-pad", "Automatycznie (wbudowany) lub ścieżka ffmpeg.exe", "Otomatik (yerleşik) veya ffmpeg.exe yolu", "تلقائي (مدمج) أو مسار ffmpeg.exe"]),
        new("MediaCompatibilityEngineHelp", ["Used when the main engine cannot decode the input. Checks decoder and output support before conversion. Custom engines require a matching ffprobe.exe.", "主引擎无法解码时自动尝试兼容引擎，转换前检查解码和输出支持。自定义引擎需配套 ffprobe.exe。", "主引擎無法解碼時自動嘗試相容引擎，轉換前檢查解碼和輸出支援。自訂引擎需配套 ffprobe.exe。", "主エンジンが入力をデコードできない場合に使用します。変換前に入出力の対応を確認します。対応する ffprobe.exe が必要です。", "기본 엔진이 입력을 디코딩하지 못할 때 사용합니다. 변환 전에 입출력 지원을 확인합니다. 일치하는 ffprobe.exe가 필요합니다.", "Se usa si el motor principal no decodifica la entrada. Comprueba la compatibilidad antes de convertir. Requiere ffprobe.exe correspondiente.", "Utilisé si le moteur principal ne peut pas décoder. Vérifie la compatibilité avant conversion. Nécessite le ffprobe.exe correspondant.", "Bei fehlendem Decoder der Hauptengine. Prüft Ein- und Ausgabe vor der Konvertierung. Passende ffprobe.exe erforderlich.", "Usado quando o motor principal não decodifica. Verifica a compatibilidade antes da conversão. Requer ffprobe.exe correspondente.", "Используется, если основной движок не декодирует файл. Проверяет поддержку до конвертации. Нужен соответствующий ffprobe.exe.", "Usato se il motore principale non decodifica. Verifica il supporto prima della conversione. Richiede ffprobe.exe corrispondente.", "Als de hoofdengine niet kan decoderen. Controleert ondersteuning vóór conversie. Bijbehorende ffprobe.exe vereist.", "Gdy główny silnik nie dekoduje pliku. Sprawdza obsługę przed konwersją. Wymaga odpowiedniego ffprobe.exe.", "Ana motor çözemediğinde kullanılır. Dönüşümden önce giriş ve çıkış desteğini kontrol eder. Eşleşen ffprobe.exe gerekir.", "تُستخدم عندما يعجز المحرك الرئيسي عن فك الترميز. تتحقق من الدعم قبل التحويل. يلزم ffprobe.exe مطابق."]),
        new("MediaCompatibilityUsingFallback", ["Using compatibility decoder", "正在使用兼容解码引擎", "正在使用相容解碼引擎", "互換デコーダーを使用中", "호환 디코더 사용 중", "Usando decodificador compatible", "Utilisation du décodeur compatible", "Kompatibler Decoder wird verwendet", "Usando decodificador compatível", "Используется совместимый декодер", "Uso del decodificatore compatibile", "Compatibele decoder wordt gebruikt", "Używanie zgodnego dekodera", "Uyumlu kod çözücü kullanılıyor", "جارٍ استخدام وحدة فك ترميز متوافقة"]),
        new("MediaCompatibilityUnsupported", ["This input codec is unsupported. Configure a compatible decoder and retry. {0}", "无法解码此输入编码。请配置支持该编码的兼容引擎后重试。{0}", "無法解碼此輸入編碼。請設定支援該編碼的相容引擎後重試。{0}", "この入力コーデックに未対応です。対応するデコーダーを設定して再試行してください。{0}", "지원하지 않는 입력 코덱입니다. 호환 디코더를 설정하고 다시 시도하세요. {0}", "Códec de entrada no compatible. Configure un decodificador compatible y reintente. {0}", "Codec non pris en charge. Configurez un décodeur compatible et réessayez. {0}", "Eingabecodec nicht unterstützt. Kompatiblen Decoder konfigurieren und erneut versuchen. {0}", "Codec não compatível. Configure um decodificador compatível e tente novamente. {0}", "Кодек не поддерживается. Настройте совместимый декодер и повторите. {0}", "Codec non supportato. Configurare un decodificatore compatibile e riprovare. {0}", "Codec niet ondersteund. Stel een compatibele decoder in en probeer opnieuw. {0}", "Nieobsługiwany kodek. Skonfiguruj zgodny dekoder i ponów próbę. {0}", "Giriş kodeği desteklenmiyor. Uyumlu çözücü ayarlayıp yeniden deneyin. {0}", "ترميز الإدخال غير مدعوم. اضبط وحدة متوافقة وأعد المحاولة. {0}"]),
        new("MediaCompatibilityMissingOutput", ["The selected engine cannot create this output. {0}", "所选引擎缺少生成此输出所需的组件。{0}", "所選引擎缺少產生此輸出所需的元件。{0}", "選択したエンジンではこの出力を作成できません。{0}", "선택한 엔진에서 이 출력을 생성할 수 없습니다. {0}", "El motor no puede crear esta salida. {0}", "Ce moteur ne peut pas créer cette sortie. {0}", "Die Engine kann diese Ausgabe nicht erstellen. {0}", "O motor não pode criar esta saída. {0}", "Движок не может создать этот результат. {0}", "Il motore non può creare questo output. {0}", "De engine kan deze uitvoer niet maken. {0}", "Silnik nie może utworzyć tego wyniku. {0}", "Motor bu çıktıyı oluşturamıyor. {0}", "لا يمكن للمحرك إنشاء هذا الإخراج. {0}"]),
        new("MediaCompatibilityUnreadable", ["The input file could not be read. Check that it is available and accessible. {0}", "无法读取输入文件。请检查文件是否可用，以及是否有读取权限。{0}", "無法讀取輸入檔案。請檢查檔案是否可用，以及是否有讀取權限。{0}", "入力ファイルを読み取れませんでした。ファイルが利用可能で、読み取り権限があるか確認してください。{0}", "입력 파일을 읽을 수 없습니다. 파일을 사용할 수 있고 읽기 권한이 있는지 확인하세요. {0}", "No se pudo leer el archivo de entrada. Compruebe que esté disponible y que tenga permiso para leerlo. {0}", "Impossible de lire le fichier d’entrée. Vérifiez qu’il est disponible et que vous pouvez y accéder. {0}", "Die Eingabedatei konnte nicht gelesen werden. Prüfen Sie, ob sie verfügbar und zugänglich ist. {0}", "Não foi possível ler o arquivo de entrada. Verifique se ele está disponível e se você tem permissão de leitura. {0}", "Не удалось прочитать входной файл. Проверьте, что он доступен и у вас есть разрешение на чтение. {0}", "Impossibile leggere il file di input. Verificare che sia disponibile e accessibile. {0}", "Het invoerbestand kon niet worden gelezen. Controleer of het beschikbaar en toegankelijk is. {0}", "Nie można odczytać pliku wejściowego. Sprawdź, czy jest dostępny i masz uprawnienia do odczytu. {0}", "Giriş dosyası okunamadı. Dosyanın kullanılabilir ve erişilebilir olduğunu kontrol edin. {0}", "تعذرت قراءة ملف الإدخال. تحقق من توفره ومن وجود إذن لقراءته. {0}"]),
        new("MediaCompatibilityDamaged", ["The input failed its decode check. Obtain a complete copy of the file and retry. {0}", "输入文件未通过解码检查。请获取完整文件后重试。{0}", "輸入檔案未通過解碼檢查。請取得完整檔案後重試。{0}", "入力がデコード検査に失敗しました。完全なファイルで再試行してください。{0}", "입력 파일이 디코딩 검사에 실패했습니다. 완전한 파일로 다시 시도하세요. {0}", "La entrada no superó la prueba de decodificación. Reintente con el archivo completo. {0}", "Échec du test de décodage. Réessayez avec un fichier complet. {0}", "Decodierprüfung fehlgeschlagen. Mit einer vollständigen Datei erneut versuchen. {0}", "A entrada falhou no teste de decodificação. Tente com um arquivo completo. {0}", "Проверка декодирования не пройдена. Повторите с полным файлом. {0}", "Verifica di decodifica fallita. Riprovare con il file completo. {0}", "Decodeercontrole mislukt. Probeer met een volledig bestand. {0}", "Test dekodowania nieudany. Ponów próbę z pełnym plikiem. {0}", "Kod çözme denetimi başarısız. Tam dosyayla yeniden deneyin. {0}", "فشل فحص فك ترميز الإدخال. أعد المحاولة بملف كامل. {0}"]),
        new("MediaCompatibilityTimedOut", ["The input decode check timed out. {0}", "输入解码检查超时。{0}", "輸入解碼檢查逾時。{0}", "入力のデコード検査がタイムアウトしました。{0}", "입력 디코딩 검사 시간이 초과되었습니다. {0}", "La prueba de decodificación agotó el tiempo. {0}", "Le test de décodage a expiré. {0}", "Zeitüberschreitung bei der Decodierprüfung. {0}", "O teste de decodificação excedeu o tempo. {0}", "Время проверки декодирования истекло. {0}", "Tempo del controllo di decodifica scaduto. {0}", "Decodeercontrole duurde te lang. {0}", "Przekroczono czas testu dekodowania. {0}", "Kod çözme denetimi zaman aşımına uğradı. {0}", "انتهت مهلة فحص فك الترميز. {0}"]),
        new("MediaCompatibilityEngineUnavailable", ["The compatibility engine is unavailable. Check its ffmpeg.exe and ffprobe.exe. {0}", "兼容引擎不可用，请检查配套的 ffmpeg.exe 与 ffprobe.exe。{0}", "相容引擎不可用，請檢查配套的 ffmpeg.exe 與 ffprobe.exe。{0}", "互換エンジンを使用できません。ffmpeg.exe と ffprobe.exe を確認してください。{0}", "호환 엔진을 사용할 수 없습니다. ffmpeg.exe와 ffprobe.exe를 확인하세요. {0}", "Motor compatible no disponible. Compruebe ffmpeg.exe y ffprobe.exe. {0}", "Moteur compatible indisponible. Vérifiez ffmpeg.exe et ffprobe.exe. {0}", "Kompatible Engine nicht verfügbar. ffmpeg.exe und ffprobe.exe prüfen. {0}", "Motor compatível indisponível. Verifique ffmpeg.exe e ffprobe.exe. {0}", "Совместимый движок недоступен. Проверьте ffmpeg.exe и ffprobe.exe. {0}", "Motore compatibile non disponibile. Controllare ffmpeg.exe e ffprobe.exe. {0}", "Compatibele engine niet beschikbaar. Controleer ffmpeg.exe en ffprobe.exe. {0}", "Zgodny silnik niedostępny. Sprawdź ffmpeg.exe i ffprobe.exe. {0}", "Uyumlu motor kullanılamıyor. ffmpeg.exe ve ffprobe.exe dosyalarını denetleyin. {0}", "المحرك المتوافق غير متاح. تحقق من ffmpeg.exe وffprobe.exe. {0}"]),
        new("MediaCompatibilityRepairDocx", ["Repair DOCX copies when import validation fails", "DOCX 导入校验失败时尝试修复副本", "DOCX 匯入驗證失敗時嘗試修復副本", "DOCX の読み込み検証失敗時にコピーを修復", "DOCX 가져오기 검사 실패 시 복사본 복구", "Reparar copias DOCX si falla la validación", "Réparer les copies DOCX en cas de validation échouée", "DOCX-Kopie bei fehlgeschlagener Prüfung reparieren", "Reparar cópias DOCX se a validação falhar", "Исправлять копии DOCX при ошибке проверки", "Riparare copie DOCX se la verifica fallisce", "DOCX-kopie herstellen bij mislukte validatie", "Napraw kopie DOCX po błędzie walidacji", "Doğrulama başarısızsa DOCX kopyalarını onar", "إصلاح نسخ DOCX عند فشل التحقق"]),
        new("MediaCompatibilityRepairDocxHelp", ["Uses LibreOffice on a temporary copy and validates it again. The original stays unchanged; repaired layout may differ.", "使用 LibreOffice 重存临时副本后再次校验。原文件保持不变，修复后的排版可能变化。", "使用 LibreOffice 重新儲存暫存副本後再次驗證。原檔案保持不變，修復後的排版可能變化。", "LibreOffice で一時コピーを再保存し、再検証します。元のファイルは変更されません。レイアウトが変わる場合があります。", "LibreOffice로 임시 복사본을 다시 저장하고 검사합니다. 원본은 변경되지 않으며 레이아웃이 달라질 수 있습니다.", "LibreOffice vuelve a guardar una copia temporal y la valida. El original no cambia; el diseño puede variar.", "LibreOffice réenregistre une copie temporaire et la valide. Original inchangé ; mise en page variable.", "LibreOffice speichert eine temporäre Kopie neu und prüft sie. Original unverändert; Layout kann abweichen.", "LibreOffice salva uma cópia temporária e a valida. Original inalterado; o layout pode mudar.", "LibreOffice пересохраняет и проверяет временную копию. Оригинал не меняется; вёрстка может отличаться.", "LibreOffice salva e verifica una copia temporanea. Originale invariato; impaginazione modificabile.", "LibreOffice slaat een tijdelijke kopie opnieuw op en valideert die. Origineel ongewijzigd; opmaak kan afwijken.", "LibreOffice zapisuje i sprawdza kopię tymczasową. Oryginał bez zmian; układ może się różnić.", "LibreOffice geçici kopyayı kaydedip doğrular. Asıl dosya değişmez; düzen farklı olabilir.", "يعيد LibreOffice حفظ نسخة مؤقتة والتحقق منها. لا يتغير الأصل؛ قد يختلف التخطيط."] )
    ]);
